// Gate: every internal link in content/docs resolves to a page, checked at the source.
//
// The site is a client-rendered TanStack Start application, so its prerendered HTML
// carries few static links, and a crawl of the output alone can miss a broken link in
// page content. This check reads every .mdx file instead. It is offline and needs no
// build. External links (http, https, mailto, tel) and pure anchors are skipped.
//
// Operation pages under /docs/<apiBaseDir>/ are generated by fumadocs-openapi from the
// documents in the openapi directory, so a link to /docs/api/<operationId> is accepted
// when some document declares that operationId.
import { existsSync, readFileSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"

import { collect, docsRoot, openapiOperations, report, root, settings } from "./doc-pages.mjs"

const operationIds = new Set(openapiOperations().keys())
const apiPrefix = `${settings.apiBaseDir}/`

// Markdown [text](target) and JSX href="target".
function targets(source) {
  return [
    ...[...source.matchAll(/\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g)].map((match) => match[1]),
    ...[...source.matchAll(/href=["']([^"']+)["']/g)].map((match) => match[1]),
  ]
}

function pageExists(base) {
  return existsSync(`${base}.mdx`) || existsSync(join(base, "index.mdx"))
}

// /docs, /docs/<page>, /docs/<section>/ and the raw Markdown route /docs/<page>.md.
function docUrlExists(url) {
  let path = url.replace(/^\/docs\/?/, "").replace(/\/$/, "")
  if (path.endsWith(".md")) path = path.slice(0, -3)
  if (path === "") return existsSync(join(docsRoot, "index.mdx"))
  if (path.startsWith(apiPrefix) && operationIds.has(path.slice(apiPrefix.length))) return true
  return pageExists(join(docsRoot, path))
}

function relativeExists(directory, target) {
  let path = target
  if (path.endsWith(".md")) path = path.slice(0, -3)
  return pageExists(resolve(directory, path))
}

const files = collect(docsRoot, ".mdx")
const errors = []

for (const file of files) {
  const source = readFileSync(file, "utf8")
  for (const raw of targets(source)) {
    const target = raw.trim()
    if (/^(https?:|mailto:|tel:|#|\/\/)/.test(target)) continue
    if (target.startsWith("[") || target.includes("](")) continue
    const path = target.split("#")[0].split("?")[0]
    if (path === "") continue
    let ok
    if (path === "/docs" || path.startsWith("/docs/")) ok = docUrlExists(path)
    // Any other absolute path must be a static file the site serves from public/.
    else if (path.startsWith("/")) ok = existsSync(join(root, "public", path))
    else ok = relativeExists(dirname(file), path)
    if (!ok) errors.push(`${relative(root, file)} -> ${target}`)
  }
}

report(errors, `Doc links OK: ${files.length} page(s), no broken internal links.`)
